command:
/*
 * Make Shadow — spawn a hostile glass Reflection of a PC (pf2e v8.1.2).
 *
 * Clones the selected player character as a level-2-weaker, hostile `character`
 * actor: adds the shadow trait + glass tint, embeds the Mirror Echo / Shattered
 * Echo / Glass Body / Shatter actions, and auto-links it to its source so Mirror
 * Cast works at once. Filed under the "Shadow Reflections" folder.
 *
 * Use: select the PC token (or assign yourself a character) -> run this macro.
 */

const pc = canvas.tokens.controlled[0]?.actor ?? game.user.character;
const api = game.modules.get("pf2e-netherworld")?.api;
if (!api?.makeShadow) {
  ui.notifications.error("Make Shadow: the Nether World module isn't active.");
  return;
}

const shadow = await api.makeShadow(pc);
if (shadow) {
  ui.notifications.info(`${shadow.name} created.`);
  shadow.sheet.render(true);
}
